using System;
using UnityEngine;
using UnityEngine.UIElements;

public class HotbarUI : MonoBehaviour
{
    private const int SlotCount = 9;

    [SerializeField] private string[] itemNames = { "Pickaxe", "Axe", "Sword", "Bow", "Torch", "Apple", "Potion", "", "" };

