using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
[Serializable]
public class InventoryEntry
{
    public string itemName;
    public int count;
    public Color color = Color.white;
}
public class InventoryData : MonoBehaviour
{
    [SerializeField] private int slotCount = 20;
    [SerializeField] private List<InventoryEntry> entries = new List<InventoryEntry>();
    public event Action OnChanged;
    public int SlotCount { get { return slotCount; } }
    public IReadOnlyList<InventoryEntry> Entries { get { return entries; } }
    public bool Add(string itemName, int count, Color color)
    {
        foreach (InventoryEntry entry in entries)
        {
            if (entry.itemName == itemName)
            {
                entry.count += count;
                Raise();
                return true;
            }
        }
        if (entries.Count >= slotCount) return false;
        entries.Add(new InventoryEntry { itemName = itemName, count = count, color = color });
        Raise();
        return true;
    }
    public void RemoveAt(int index)
    {
        if (index < 0 || index >= entries.Count) return;
        entries.RemoveAt(index);
        Raise();
    }
    private void Raise()
    {
        if (OnChanged != null) OnChanged();
    }
