**Plan**
- A singleton `CurrencyManager` (lazy `Instance`, `DontDestroyOnLoad`) holds the balance.
- `Add(amount)` and `TrySpend(amount)` validate input, update the balance and raise `OnChanged(newBalance)`.
- The balance is loaded from PlayerPrefs on creation and saved after every change.

```csharp
using System;
using UnityEngine;

public class CurrencyManager : MonoBehaviour
{
    private const string SaveKey = "Currency.Coins";

    private static CurrencyManager instance;
    private static bool quitting;

    public static CurrencyManager Instance
    {
        get
        {
            if (instance == null && !quitting)
            {
                instance = FindObjectOfType<CurrencyManager>();
                if (instance == null)
                {
                    GameObject go = new GameObject("CurrencyManager");
                    instance = go.AddComponent<CurrencyManager>();
                }
            }
            return instance;
        }
    }

    [SerializeField] private int startingCoins = 0;

    private int balance;
    private bool loaded;

    public event Action<int> OnChanged;
    public int Balance
    {
        get
        {
            EnsureLoaded();
            return balance;
        }
    }

    private void Awake()
    {
        if (instance != null && instance != this)
        {
            Destroy(gameObject);
            return;
        }
        instance = this;
        DontDestroyOnLoad(gameObject);
        EnsureLoaded();
    }

    private void OnApplicationQuit()
    {
        quitting = true;
        Save();
    }

    private void EnsureLoaded()
    {
        if (loaded) return;
        balance = PlayerPrefs.GetInt(SaveKey, startingCoins);
        loaded = true;
    }

    public void Add(int amount)
    {
        if (amount <= 0) return;
        EnsureLoaded();
        long total = (long)balance + amount;
        balance = (int)Math.Min(total, int.MaxValue);
        Changed();
    }

    public bool TrySpend(int amount)
    {
        EnsureLoaded();
        if (amount < 0 || balance < amount) return false;
        balance -= amount;
        Changed();
        return true;
    }

    public bool CanAfford(int amount)
    {
        EnsureLoaded();
        return amount >= 0 && balance >= amount;
    }

    private void Changed()
    {
        Save();
        if (OnChanged != null) OnChanged(balance);
    }

    private void Save()
    {
        PlayerPrefs.SetInt(SaveKey, balance);
        PlayerPrefs.Save();
    }
}
```

Any script can call `CurrencyManager.Instance.Add(10)` or `TrySpend(25)`; the instance is created on first use and survives scene loads. Adds saturate at `int.MaxValue` instead of overflowing, spending below zero is refused, and every change is written to PlayerPrefs before `OnChanged` fires, so UI and saves never disagree.

