- Ground is detected with a thin `OverlapBox` just below the collider, ignoring triggers and the player itself.

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D), typeof(BoxCollider2D))]
public class PlatformerController2D : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float acceleration = 70f;
    [SerializeField] private float deceleration = 90f;
    [SerializeField] private float jumpVelocity = 14f;
    [SerializeField] private float coyoteTime = 0.1f;
    [SerializeField] private float jumpBufferTime = 0.12f;
    [SerializeField] private float fallGravityMultiplier = 2.2f;
    [SerializeField] private float jumpCutMultiplier = 0.5f;
    [SerializeField] private float groundCheckDistance = 0.06f;
    [SerializeField] private LayerMask groundMask = ~0;

    private Rigidbody2D body;
    private BoxCollider2D box;
    private float inputX;
    private float coyoteCounter;
    private float bufferCounter;
    private float baseGravity;

    public bool Grounded { get; private set; }

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        box = GetComponent<BoxCollider2D>();
        body.freezeRotation = true;
        baseGravity = body.gravityScale;
    }

    private void Update()
    {
        inputX = Input.GetAxisRaw("Horizontal");
        Grounded = CheckGround();

        coyoteCounter = Grounded ? coyoteTime : coyoteCounter - Time.deltaTime;
        if (Input.GetButtonDown("Jump")) bufferCounter = jumpBufferTime;
        else bufferCounter -= Time.deltaTime;

        if (bufferCounter > 0f && coyoteCounter > 0f)
        {
            body.velocity = new Vector2(body.velocity.x, jumpVelocity);
            bufferCounter = 0f;
            coyoteCounter = 0f;
        }

        if (Input.GetButtonUp("Jump") && body.velocity.y > 0f)
            body.velocity = new Vector2(body.velocity.x, body.velocity.y * jumpCutMultiplier);
    }

    private void FixedUpdate()
    {
        float target = inputX * moveSpeed;
        float rate = Mathf.Abs(target) > 0.01f ? acceleration : deceleration;
        float vx = Mathf.MoveTowards(body.velocity.x, target, rate * Time.fixedDeltaTime);
        body.velocity = new Vector2(vx, body.velocity.y);
        body.gravityScale = body.velocity.y < -0.1f ? baseGravity * fallGravityMultiplier : baseGravity;
    }

    private bool CheckGround()
    {
        Bounds b = box.bounds;
        Vector2 center = new Vector2(b.center.x, b.min.y - groundCheckDistance * 0.5f);
        Vector2 size = new Vector2(b.size.x * 0.9f, groundCheckDistance);
        foreach (Collider2D hit in Physics2D.OverlapBoxAll(center, size, 0f, groundMask))
        {
            if (hit.isTrigger || hit.gameObject == gameObject) continue;
            return true;
        }
        return false;
    }
}
```

Coyote time and the jump buffer are just two countdown timers. The coyote timer is refilled every frame the player stands on ground, and the buffer timer is refilled on a jump press; a jump happens whenever both are above zero, so a press just before landing and a press just after leaving a ledge both work. The jump cut on release gives short hops for taps and full jumps for held presses.

