        actionLabel = MakeLabel(panel);
        doc.rootVisualElement.Add(panel);
    }

    private Label MakeLabel(VisualElement parent)
    {
        Label label = new Label();
        label.style.color = Color.white;
        label.style.fontSize = 26;
        parent.Add(label);
        return label;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        satiation -= 2f * dt;
        energy -= 1.5f * dt;
        money -= 1f * dt;
        switch (current)
        {
            case Act.Eat: satiation += 16f * dt; money -= 1.5f * dt; break;
            case Act.Sleep: energy += 12f * dt; satiation -= 0.5f * dt; break;
            case Act.Work: money += 8f * dt; energy -= 3f * dt; satiation -= 1f * dt; break;
        }
        satiation = Mathf.Clamp(satiation, 0f, 100f);
        energy = Mathf.Clamp(energy, 0f, 100f);
        money = Mathf.Clamp(money, 0f, 100f);

        if (Time.time >= nextThink)
        {
            nextThink = Time.time + thinkInterval;
            Think();
        }
        needsLabel.text = string.Format("Food {0:0}  Energy {1:0}  Money {2:0}", satiation, energy, money);
        actionLabel.text = string.Format("Doing: {0}   (eat {1:0.00}, sleep {2:0.00}, work {3:0.00})", current, scores[0], scores[1], scores[2]);
    }

    private void Think()
    {
        scores[(int)Act.Eat] = Curve(satiation, 2f);
        scores[(int)Act.Sleep] = Curve(energy, 2f);
        scores[(int)Act.Work] = Curve(money, 1.5f) * 0.85f;
        scores[(int)current] += stickiness;

        int best = 0;
        for (int i = 1; i < scores.Length; i++) if (scores[i] > scores[best]) best = i;
        current = (Act)best;
    }

    // 0 when the need is full, 1 when it is empty; the exponent makes urgency rise sharply near empty.
    private static float Curve(float level, float exponent)
    {
        return Mathf.Pow(1f - level / 100f, exponent);
    }
}
```

Utility AI scores every option with the same 0 to 1 scale, so very different goals can be compared without hand-written priority rules. The exponent makes a need ignorable while it is nearly full and dominant when it is nearly empty, and the small stickiness bonus to the running action stops the agent from switching back and forth when two scores are close. Add a new behaviour by adding one enum value, one effect and one curve.

**Plan**
- A `NavMeshAgent` enemy has health and a public `TakeDamage`; above 20% health it chases the player, below it switches to Flee.
- Fleeing samples random points on the NavMesh and accepts the first one that is at least 10 m farther from the player than the enemy is now; it picks a new point when it arrives or when the player gets within 6 m.
- Press H to damage the enemy 15 HP for testing, and a color shows the state (red chasing, yellow fleeing).

```csharp
using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class FleeingEnemy : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float fleeThreshold = 0.2f;
    [SerializeField] private float chaseSpeed = 3.5f;
    [SerializeField] private float fleeSpeed = 6f;
    [SerializeField] private float fleeSearchRadius = 25f;
    [SerializeField] private float minExtraDistance = 10f;
    [SerializeField] private float rePickDistance = 6f;

    private NavMeshAgent agent;
    private Renderer body;
    private float health;
    private bool hasFleeTarget;

    public bool IsFleeing { get { return health <= maxHealth * fleeThreshold; } }

    private void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        body = GetComponentInChildren<Renderer>();
        health = maxHealth;
        if (player == null)
        {
            GameObject found = GameObject.FindWithTag("Player");
            if (found != null) player = found.transform;
        }
    }

    public void TakeDamage(float amount)
    {
        health = Mathf.Max(0f, health - amount);
        hasFleeTarget = false;
    }

    private void Update()
    {
        if (player == null || !agent.isOnNavMesh) return;
        if (Input.GetKeyDown(KeyCode.H)) TakeDamage(15f);

        if (IsFleeing) Flee();
        else Chase();

        if (body != null) body.material.color = IsFleeing ? Color.yellow : Color.red;
    }

    private void Chase()
    {
        agent.speed = chaseSpeed;
        agent.SetDestination(player.position);
    }

    private void Flee()
    {
        agent.speed = fleeSpeed;
        float playerDistance = Vector3.Distance(transform.position, player.position);
        bool arrived = hasFleeTarget && !agent.pathPending && agent.remainingDistance <= agent.stoppingDistance + 0.5f;
        if (!hasFleeTarget || arrived || playerDistance < rePickDistance) hasFleeTarget = TryPickFleePoint();
    }

    private bool TryPickFleePoint()
    {
        float currentDistance = Vector3.Distance(transform.position, player.position);
        for (int attempt = 0; attempt < 15; attempt++)
        {
            Vector3 candidate = transform.position + Random.insideUnitSphere * fleeSearchRadius;
            NavMeshHit hit;
            if (!NavMesh.SamplePosition(candidate, out hit, 3f, NavMesh.AllAreas)) continue;
            if (Vector3.Distance(hit.position, player.position) < currentDistance + minExtraDistance) continue;
            NavMeshPath path = new NavMeshPath();
            if (agent.CalculatePath(hit.position, path) && path.status == NavMeshPathStatus.PathComplete)
            {
                agent.SetPath(path);
                return true;
            }
        }
        return false;
    }
}
```

Random sampling plus an acceptance test is simple and avoids the classic flee bug of running straight into a dead end: a point is only used when the NavMesh can actually reach it and it ends up clearly farther from the player. Re-picking when the player gets close means a cornered enemy keeps looking for a new escape instead of standing still at its old target.

**Plan**
- Left mouse starts a swing that lasts `swingDuration`; during the active window (after a short wind-up) every frame calls `Physics.OverlapSphere` in front of the player.
- A `HashSet` of already-hit root objects makes sure each enemy is damaged only once per swing; it is cleared when the next swing starts.
- Damage goes through `SendMessageUpwards("TakeDamage")`, and a cooldown plus a visual sweep of a cube prevent spamming and show the hit area.

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class MeleeAttack : MonoBehaviour
{
    [SerializeField] private Transform attackPoint;
    [SerializeField] private float radius = 1.2f;
    [SerializeField] private float damage = 20f;
    [SerializeField] private float windUp = 0.1f;
    [SerializeField] private float activeTime = 0.2f;
    [SerializeField] private float cooldown = 0.5f;
    [SerializeField] private LayerMask hitMask = ~0;

    private readonly HashSet<GameObject> hitThisSwing = new HashSet<GameObject>();
    private float nextAttack;
    private bool swinging;
    private Transform visual;

    private void Start()
    {
        if (attackPoint == null)
        {
            GameObject point = new GameObject("AttackPoint");
            point.transform.SetParent(transform, false);
            point.transform.localPosition = new Vector3(0f, 1f, 1.2f);
            attackPoint = point.transform;
        }
        GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
        Destroy(cube.GetComponent<Collider>());
        cube.transform.SetParent(attackPoint, false);
        cube.transform.localScale = Vector3.one * radius * 1.6f;
        cube.GetComponent<Renderer>().material.color = new Color(1f, 0.3f, 0.2f);
        cube.SetActive(false);
        visual = cube.transform;
    }

    private void Update()
    {
        if (Input.GetMouseButtonDown(0) && !swinging && Time.time >= nextAttack)
            StartCoroutine(Swing());
    }

    private IEnumerator Swing()
    {
        swinging = true;
        nextAttack = Time.time + cooldown;
        hitThisSwing.Clear();
        yield return new WaitForSeconds(windUp);

        visual.gameObject.SetActive(true);
        float end = Time.time + activeTime;
        while (Time.time < end)
        {
            DealDamage();
            yield return null;
        }
        visual.gameObject.SetActive(false);
        swinging = false;
    }

    private void DealDamage()
    {
        Collider[] hits = Physics.OverlapSphere(attackPoint.position, radius, hitMask, QueryTriggerInteraction.Ignore);
        foreach (Collider hit in hits)
        {
            if (hit.transform.IsChildOf(transform)) continue;
            GameObject root = hit.attachedRigidbody != null ? hit.attachedRigidbody.gameObject : hit.transform.root.gameObject;
            if (!hitThisSwing.Add(root)) continue;
            hit.SendMessageUpwards("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
        }
    }

    private void OnDrawGizmosSelected()
    {
        Transform p = attackPoint != null ? attackPoint : transform;
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(p.position, radius);
    }
}
```

An enemy usually has several colliders, so tracking hits by its root object (the Rigidbody owner, or the top parent) is what makes it count once per swing instead of once per limb. `HashSet.Add` returns false when the object is already in the set, which turns the check and the insert into one line. Checking every frame of the active window catches targets that walk into the arc during the swing.

