```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.UIElements;

public class HitscanGun : MonoBehaviour
{
    [SerializeField] private Camera aimCamera;
    [SerializeField] private Transform muzzle;
    [SerializeField] private float damage = 25f;
    [SerializeField] private float range = 120f;
    [SerializeField] private float fireRate = 8f;
    [SerializeField] private int magazineSize = 12;
    [SerializeField] private int reserveAmmo = 48;
    [SerializeField] private float reloadTime = 1.5f;
    [SerializeField] private LayerMask hitMask = ~0;

    private int ammo;
    private float nextShot;
    private bool reloading;
    private GameObject flash;
    private Label ammoLabel;

    private void Start()
    {
        ammo = magazineSize;
        if (aimCamera == null) aimCamera = Camera.main;
        if (muzzle == null) muzzle = transform;
        BuildFlash();
        BuildUi();
        RefreshUi();
    }

    private void Update()
    {
        if (reloading) return;
        if (Input.GetKeyDown(KeyCode.R)) StartCoroutine(Reload());
        else if (Input.GetMouseButton(0) && Time.time >= nextShot)
        {
            if (ammo <= 0) { StartCoroutine(Reload()); return; }
            nextShot = Time.time + 1f / fireRate;
            Shoot();
        }
    }

    private void Shoot()
    {
        ammo--;
        RefreshUi();
        StartCoroutine(Flash());
        Ray ray = aimCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
        RaycastHit hit;
        if (!Physics.Raycast(ray, out hit, range, hitMask, QueryTriggerInteraction.Ignore)) return;
        hit.collider.SendMessageUpwards("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
        GameObject mark = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        Destroy(mark.GetComponent<Collider>());
        mark.transform.position = hit.point + hit.normal * 0.02f;
        mark.transform.localScale = Vector3.one * 0.12f;
        mark.GetComponent<Renderer>().material.color = Color.yellow;
        Destroy(mark, 2f);
    }

    private IEnumerator Reload()
    {
        int needed = magazineSize - ammo;
        if (needed <= 0 || reserveAmmo <= 0) yield break;
        reloading = true;
        ammoLabel.text = "Reloading...";
        yield return new WaitForSeconds(reloadTime);
        int taken = Mathf.Min(needed, reserveAmmo);
        ammo += taken;
        reserveAmmo -= taken;
        reloading = false;
        RefreshUi();
    }

    private IEnumerator Flash()
    {
        flash.SetActive(true);
        yield return new WaitForSeconds(0.05f);
        flash.SetActive(false);
    }

    private void BuildFlash()
    {
        flash = GameObject.CreatePrimitive(PrimitiveType.Cube);
        Destroy(flash.GetComponent<Collider>());
        flash.transform.SetParent(muzzle, false);
        flash.transform.localScale = Vector3.one * 0.15f;
        flash.GetComponent<Renderer>().material.color = new Color(1f, 0.85f, 0.3f);
        Light glow = flash.AddComponent<Light>();
        glow.type = LightType.Point;
        glow.color = new Color(1f, 0.8f, 0.3f);
        glow.range = 6f;
        glow.intensity = 3f;
        flash.SetActive(false);
    }

    private void BuildUi()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        ammoLabel = new Label();
        ammoLabel.style.position = Position.Absolute;
        ammoLabel.style.right = 30;
        ammoLabel.style.bottom = 24;
        ammoLabel.style.fontSize = 40;
        ammoLabel.style.color = Color.white;
        doc.rootVisualElement.Add(ammoLabel);
    }

    private void RefreshUi()
    {
        ammoLabel.text = ammo + " / " + reserveAmmo;
    }
}
```

Firing is gated by two independent checks: a timestamp for the rate of fire and a `reloading` flag that blocks everything during the reload, so holding the mouse button can never fire faster than `fireRate` or during a reload. Reload moves only as many rounds as the magazine needs, and a hit is reported to whatever component upstream has a `TakeDamage` method, so the gun works with any target.

**Plan**
- `ProjectileLauncher` keeps a `Queue` of inactive projectile objects, prewarmed with `poolSize` spheres, each with a `Rigidbody` and a runtime-added helper `PooledProjectile`.
- Left mouse takes one from the queue (or creates one if the pool ran out), places it at the muzzle and launches it; no `Instantiate` or `Destroy` happens during play after the warm-up.
- A projectile returns itself to the pool on its first collision or when its lifetime ends, resetting its velocity and deactivating.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class ProjectileLauncher : MonoBehaviour
{
    [SerializeField] private Transform muzzle;
    [SerializeField] private int poolSize = 20;
    [SerializeField] private float speed = 30f;
    [SerializeField] private float lifetime = 3f;
    [SerializeField] private float fireRate = 6f;
    [SerializeField] private float damage = 10f;

    private readonly Queue<PooledProjectile> pool = new Queue<PooledProjectile>();
    private Transform container;
    private float nextShot;

    public int Available { get { return pool.Count; } }

    private void Start()
    {
        if (muzzle == null) muzzle = transform;
        container = new GameObject("ProjectilePool").transform;
        for (int i = 0; i < poolSize; i++) pool.Enqueue(Create());
    }

    private void Update()
    {
        if (Input.GetMouseButton(0) && Time.time >= nextShot)
        {
            nextShot = Time.time + 1f / fireRate;
            Fire();
        }
    }

    private PooledProjectile Create()
    {
        GameObject sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        sphere.name = "Projectile";
        sphere.transform.SetParent(container, false);
        sphere.transform.localScale = Vector3.one * 0.3f;
        sphere.GetComponent<Renderer>().material.color = new Color(1f, 0.5f, 0.1f);
        Rigidbody body = sphere.AddComponent<Rigidbody>();
        body.useGravity = false;
        body.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
        PooledProjectile projectile = sphere.AddComponent<PooledProjectile>();
        projectile.Setup(this, damage);
        sphere.SetActive(false);
        return projectile;
    }

    private void Fire()
    {
        PooledProjectile projectile = pool.Count > 0 ? pool.Dequeue() : Create();
        projectile.Launch(muzzle.position, muzzle.forward * speed, lifetime);
    }

    public void Return(PooledProjectile projectile)
    {
        projectile.gameObject.SetActive(false);
        pool.Enqueue(projectile);
    }
}

// Helper behaviour; it is only ever added to pooled spheres at runtime by the launcher above.
public class PooledProjectile : MonoBehaviour
{
    private ProjectileLauncher owner;
    private Rigidbody body;
    private float damage;
    private float expireAt;
    private bool active;

    public void Setup(ProjectileLauncher launcher, float hitDamage)
    {
        owner = launcher;
        damage = hitDamage;
        body = GetComponent<Rigidbody>();
    }

    public void Launch(Vector3 position, Vector3 velocity, float lifetime)
    {
        transform.position = position;
        gameObject.SetActive(true);
        body.velocity = velocity;
        body.angularVelocity = Vector3.zero;
        expireAt = Time.time + lifetime;
        active = true;
    }

    private void Update()
    {
        if (active && Time.time >= expireAt) Finish();
    }

    private void OnCollisionEnter(Collision collision)
    {
        if (!active) return;
        collision.collider.SendMessageUpwards("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
        Finish();
    }

    private void Finish()
    {
        active = false;
        body.velocity = Vector3.zero;
        owner.Return(this);
    }
}
```

Object pooling avoids creating and destroying objects while the player fires, which is what causes garbage-collection hitches in fast shooters. The `active` flag stops a projectile from being returned twice when a collision and the lifetime expiry happen in the same frame, which would put the same object in the queue twice, and continuous collision detection keeps fast projectiles from passing through thin walls.

