    public bool IsDead { get { return health <= 0f; } }

    public void TakeDamage(float amount)
    {
        health -= amount;
        GetComponent<Renderer>().material.color = Color.Lerp(Color.black, Color.red, Mathf.Clamp01(health / 45f));
        if (IsDead) Destroy(gameObject, 0.1f);
    }
}

public class BreakableCrate : MonoBehaviour, IDamageable
{
    private int hitsLeft = 3;

    public bool IsDead { get { return hitsLeft <= 0; } }

